// ================================================================ deck 1 visuals: sequences, series, AP, means, sums of powers
// title: an AP climbs by equal steps, a GP by equal multiples
const apT = ap(2, 3).list(6), gpT = gp(2, 2).list(6);
must(apT.map(String).join() === '2,5,8,11,14,17' && gpT.map(String).join() === '2,4,8,16,32,64', 'title sequences');
const titlePlot = plot({ x: [0, 7], y: [0, 70], xl: 'n (position of the term)', yl: 'value of the term', pts: [...apT.map((v, i) => [i + 1, N(v), String(v), 'free']), ...gpT.map((v, i) => [i + 1, N(v), String(v), 'free'])], series: [{ label: 'equal steps: 2, 5, 8, 11, 14, 17', points: apT.map((v, i) => [i + 1, N(v)]), kind: 'line' }, { label: 'equal multiples: 2, 4, 8, 16, 32, 64', points: gpT.map((v, i) => [i + 1, N(v)]), kind: 'line' }] }, 'Plot of two sequences against their position: 2, 5, 8, 11, 14, 17 rises along a straight line because each term adds 3, while 2, 4, 8, 16, 32, 64 climbs faster and faster because each term doubles.', 'Add the same number each time, or multiply by the same number each time.');
// three ways a sequence is given
const sq1 = range(1, 5).map((n) => n * n - 3 * n + 4);
const sq2 = [2]; for (let k = 1; k < 5; k++) sq2.push(3 * sq2[k - 1] - 2);
const sq3 = range(1, 5).map((n) => new Rat(1n, BigInt(n * (n + 1))));
must(sq1.join() === '2,2,4,8,14' && sq2.join() === '2,4,10,28,82' && sq3.map(String).join() === '1/2,1/6,1/12,1/20,1/30', 'three sequences');
const rulesTable = table(['Rule', 'First five terms'], [[r`$a_n = n^2 - 3n + 4$ (formula for the $n$th term)`, `$${sq1.join(', ')}, \\ldots$`], [r`$a_1 = 2$ and $a_{n+1} = 3a_n - 2$ (each term from the one before)`, `$${sq2.join(', ')}, \\ldots$`], [r`$a_n = \dfrac{1}{n(n+1)}$ (formula with fractions)`, `$${sq3.map(tx).join(', ')}, \\ldots$`]], 'Table of three sequences: the formula n squared minus 3n plus 4 gives 2, 2, 4, 8, 14; the rule that starts at 2 and sends each term a to 3a minus 2 gives 2, 4, 10, 28, 82; and one over n times n plus 1 gives one half, one sixth, one twelfth, one twentieth, one thirtieth.', 'A sequence is a list given by a formula or by a rule from the earlier terms.');
// a series: partial sums of a_n = 3n - 2
